import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';
void main()=>runApp(const App());class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp.router(title:'Veyra Chauffeur',theme:ThemeData(useMaterial3:true),routerConfig:r);}
final r=GoRouter(initialLocation:'/login',routes:[for(final x in ['/login','/kyc','/home','/request','/agenda','/ride','/wallet','/chat'])GoRoute(path:x,builder:(c,s)=>Screen(x))]);
class Screen extends StatelessWidget{final String p;const Screen(this.p,{super.key});@override Widget build(BuildContext c){final d=<String,List<String>>{
'/login':['Veyra Chauffeur','Email','Mot de passe'],'/kyc':['Inscription VTC','Identité','Entreprise SIREN/SIRET','Carte professionnelle VTC','Véhicule','Assurance','RIB'],'/home':['Demandes disponibles','Tri: date / plus récentes','Marseille → Nice','Aucun tri par proximité'],'/request':['Détail demande','Date • Heure • Passagers • Bagages','Votre prix (€)','Aucun prix concurrent visible'],'/agenda':['Agenda','Réservations confirmées','Offres en attente'],'/ride':['Course','Carte','Je suis en route','Je suis arrivé','PIN client 4 chiffres','Démarrer','Terminer'],'/wallet':['Portefeuille','À recevoir ONLINE','Dette commission CASH','Seuils 50 € / 100 € / 150 €'],'/chat':['Chat Veyra','Texte uniquement après confirmation']};final a=d[p]!;
return Scaffold(appBar:AppBar(title:Text(a.first)),body:ListView(padding:const EdgeInsets.all(20),children:[for(final t in a.skip(1))Card(child:ListTile(title:Text(t))),if(p=='/login')FilledButton(onPressed:()=>c.go('/kyc'),child:const Text('Connexion')),if(p=='/kyc')FilledButton(onPressed:()=>c.go('/home'),child:const Text('Envoyer pour vérification')),if(p=='/home')FilledButton(onPressed:()=>c.go('/request'),child:const Text('Voir demande')),if(p=='/request')FilledButton(onPressed:()=>c.go('/agenda'),child:const Text('Envoyer mon offre')),if(p=='/agenda')FilledButton(onPressed:()=>c.go('/ride'),child:const Text('Ouvrir la course'))]));}}
